/* Progressive motion: content is never hidden while waiting for JavaScript. */
(()=>{
 'use strict';
 const root=document.documentElement;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const toggle=document.querySelector('#motion-toggle');
 let userPaused=false;try{userPaused=localStorage.getItem('tcc-motion-paused')==='true'}catch{}
 let paused=true,scrollFrame=0,pointerFrame=0;
 const progress=document.querySelector('.thread-progress>span');
 const hero=document.querySelector('.hero-visual'),photo=document.querySelector('.hero-photo-frame');
 const animations=new Set();
 function animate(node,frames,options){if(paused||!node.animate)return;const a=node.animate(frames,options);animations.add(a);a.finished.then(()=>{animations.delete(a);a.cancel()}).catch(()=>animations.delete(a));return a}
 function updateProgress(){scrollFrame=0;if(paused||!progress)return;const distance=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${distance>0?Math.min(1,Math.max(0,scrollY/distance)):0})`}
 function applyPreference(){paused=reduced.matches||userPaused;root.classList.toggle('motion-off',paused);toggle.setAttribute('aria-pressed',String(paused));toggle.textContent=reduced.matches?'Reduced motion enabled':paused?'Resume effects':'Pause effects';toggle.setAttribute('aria-disabled',String(reduced.matches));if(paused){animations.forEach(a=>a.cancel());animations.clear();photo.style.transform='';document.querySelectorAll('.selection-spark').forEach(n=>n.remove())}else updateProgress()}
 toggle.addEventListener('click',()=>{if(reduced.matches)return;userPaused=!userPaused;try{localStorage.setItem('tcc-motion-paused',String(userPaused))}catch{}applyPreference()});reduced.addEventListener('change',applyPreference);applyPreference();
 addEventListener('scroll',()=>{if(!paused&&!scrollFrame)scrollFrame=requestAnimationFrame(updateProgress)},{passive:true});addEventListener('resize',()=>{if(!paused&&!scrollFrame)scrollFrame=requestAnimationFrame(updateProgress)},{passive:true});
 if('IntersectionObserver' in window){const seen=new WeakSet();const reveal=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;reveal.unobserve(entry.target);animate(entry.target,[{opacity:0,transform:'translateY(24px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,delay:entry.target.classList.contains('product')?(Number(entry.target.dataset.revealIndex)||0)%3*65:0,easing:'cubic-bezier(.2,.75,.25,1)'})}},{threshold:.08});const observe=()=>document.querySelectorAll('.product,.section-heading,.custom-section,.story,.steps article,.film-card,.contact-section').forEach((n,i)=>{if(seen.has(n))return;seen.add(n);n.dataset.revealIndex=i;reveal.observe(n)});observe();new MutationObserver(observe).observe(document.querySelector('#products'),{childList:true});const videoObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(!entry.isIntersecting)entry.target.pause()},{threshold:0});document.querySelectorAll('video').forEach(v=>videoObserver.observe(v))}
 document.querySelectorAll('video').forEach(video=>video.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause()})));
 const fine=matchMedia('(hover: hover) and (pointer: fine)');
 hero.addEventListener('pointermove',event=>{if(paused||!fine.matches||pointerFrame)return;const x=event.clientX,y=event.clientY;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;if(paused)return;const rect=hero.getBoundingClientRect();const dx=(x-rect.left)/rect.width-.5,dy=(y-rect.top)/rect.height-.5;photo.style.transform=`perspective(900px) rotateY(${dx*5}deg) rotateX(${-dy*4}deg) rotate(3deg)`})});hero.addEventListener('pointerleave',()=>photo.style.transform='');
 document.addEventListener('click',event=>{const button=event.target.closest('[data-add],#detail-add');if(!button||paused)return;const start=button.getBoundingClientRect(),target=document.querySelector('#bag-open').getBoundingClientRect();const dot=document.createElement('span');dot.className='selection-spark';dot.textContent='✿';dot.setAttribute('aria-hidden','true');dot.style.left=start.left+start.width/2+'px';dot.style.top=start.top+'px';document.body.append(dot);const animation=animate(dot,[{opacity:1,transform:'translate(0,0) rotate(0) scale(1)'},{opacity:1,offset:.5,transform:`translate(${(target.left-start.left-start.width/2)*.6}px,${(target.top-start.top)*.55-45}px) rotate(120deg) scale(1.3)`},{opacity:0,transform:`translate(${target.left+target.width/2-start.left-start.width/2}px,${target.top-start.top}px) rotate(240deg) scale(.3)`}],{duration:800,easing:'cubic-bezier(.3,.6,.2,1)'});if(animation)animation.finished.finally(()=>dot.remove()).catch(()=>{});else dot.remove()});
})();
(()=>{const header=document.querySelector('.site-header');if('ResizeObserver' in window)new ResizeObserver(()=>document.documentElement.style.setProperty('--header-offset',Math.ceil(header.getBoundingClientRect().height+18)+'px')).observe(header)})();
